import{_ as a,c as t,o as r,ae as o}from"./chunks/framework.Dgg8-8ov.js";const p=JSON.parse('{"title":"Aalenian Survival","description":"","frontmatter":{"prev":true,"next":true},"headers":[],"relativePath":"servers/survival.md","filePath":"servers/survival.md"}'),l={name:"servers/survival.md"};function i(s,e,n,u,h,d){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="aalenian-survival" tabindex="-1">Aalenian Survival <a class="header-anchor" href="#aalenian-survival" aria-label="Permalink to &quot;Aalenian Survival&quot;">​</a></h1><p>The <strong>Aalenian Survival</strong> Path of Titans Server is is structured like officials but with modded playables.</p><h2 id="growth" tabindex="-1">Growth <a class="header-anchor" href="#growth" aria-label="Permalink to &quot;Growth&quot;">​</a></h2><ul><li>The hatchling tutorial cave is disabled and you will spawn at 0 growth</li><li>Quest rewards (growth and marks) are multiplied by 5</li><li>Death removes 0.1 growth, which is half of a growth stage</li><li>Death can set you back to previous growth stages</li></ul><h2 id="teleportation" tabindex="-1">Teleportation <a class="header-anchor" href="#teleportation" aria-label="Permalink to &quot;Teleportation&quot;">​</a></h2><ul><li>Solo-friendly waystones are enabled, allowing transport from one to another. No more begging in global for a waystone!</li><li>Custom teleport stones can be found accross the map, allowing you to go to waystones and other teleport stones.</li><li>All teleportation requires a 30 second out-of-combat sleeping period</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Simply do not violate the rules outlined in the <a href="/guidelines.html">Community Guidelines</a></p>',8)]))}const v=a(l,[["render",i]]);export{p as __pageData,v as default};
